const crypto = require('crypto');
const input = $input.first().json;
const body = input.body || input;

const token = crypto.randomBytes(32).toString('hex');
const expiresAt = new Date(Date.now() + (body.expires_days || 7) * 24 * 60 * 60 * 1000);

return [{ json: {
  token: token,
  report_type: body.report_type || 'seo_weekly',
  client_id: body.client_id,
  title: body.title || 'Performance Report',
  expires_at: expiresAt.toISOString(),
  created_by: body.created_by || 'system'
}}];

const input = $input.first().json;
const params = input.params || {};
const token = params.token || '';
if (!token) return [{ json: { error: true, message: 'Invalid token' } }];
return [{ json: { token } }];

const reportMeta = $node['Validate Token'].json;
const reportData = $input.first().json;

if (!reportMeta.id) {
  return [{ json: { error: true, html: '<h1>Report not found or expired</h1>' } }];
}

let metrics = {};
try { metrics = JSON.parse(reportData.metrics || '{}'); } catch(e) {}

// Update view count
const viewCount = (reportMeta.view_count || 0) + 1;

const html = `<!DOCTYPE html><html><head><title>${reportMeta.title} - ${reportMeta.company_name}</title><meta charset="utf-8"><style>body{font-family:-apple-system,BlinkMacSystemFont,sans-serif;max-width:800px;margin:0 auto;padding:20px;color:#333}h1{color:#0076D7}h2{border-bottom:2px solid #eee;padding-bottom:8px}.metric{display:inline-block;background:#f5f5f5;padding:15px 25px;margin:5px;border-radius:8px;text-align:center}.metric .value{font-size:24px;font-weight:bold;color:#0076D7}.metric .label{font-size:12px;color:#666;margin-top:4px}.footer{margin-top:40px;padding-top:20px;border-top:1px solid #eee;color:#999;font-size:12px}</style></head><body><h1>${reportMeta.title}</h1><p><strong>${reportMeta.company_name}</strong> | Generated: ${new Date().toLocaleDateString('id-ID')}</p><h2>Summary</h2><div>${JSON.stringify(metrics).substring(0, 500)}</div><div class="footer"><p>Report generated by GreeVo | Expires: ${new Date(reportMeta.expires_at).toLocaleDateString('id-ID')}</p></div></body></html>`;

return [{ json: { html, view_count: viewCount, report_id: reportMeta.id } }];
